/// Provider ids that participate in live RRF fusion in the browser worker.
/// These are the CORS-readable subset of [`WEB_SEARCH_PROVIDER_REGISTRY`].
///
/// Issue #180 expands the default plan to also include Internet Archive and
/// Wiktionary, in the priority order requested in the issue body. Issue #400
/// appends Wikinews as a CORS-readable news source:
/// `DuckDuckGo` → Internet Archive → Wikipedia → Wikidata → Wiktionary →
/// Wikinews.
/// The remaining providers in the registry still feed the connectivity
/// dashboard and the case study.
pub const WEB_SEARCH_PROVIDERS: &[&str] = &[
    "duckduckgo",
    "internet-archive",
    "wikipedia",
    "wikidata",
    "wiktionary",
    "wikinews",
    "wikiquote",
];

/// Default plan id list returned to JS. JS uses this to seed the planner
/// even when the live `fetch()` is offline.
#[must_use]
pub fn default_search_plan_ids() -> Vec<String> {
    WEB_SEARCH_PROVIDERS
        .iter()
        .map(|id| (*id).to_string())
        .collect()
}

/// Build the `web_search:*` evidence prefix for a given query/language.
///
/// The browser worker appends per-provider rank lines after these prefixes;
/// the offline solver records the same prefixes through `EventLog`.
#[must_use]
pub fn build_request_evidence(query: &str, language: &str) -> Vec<String> {
    let mut lines: Vec<String> = Vec::new();
    lines.push(format!("web_search:request:{query}"));
    if !language.is_empty() {
        lines.push(format!("web_search:language:{language}"));
    }
    for provider in WEB_SEARCH_PROVIDERS {
        lines.push(format!("web_search:provider:{provider}"));
    }
    lines.push(format!("web_search:combined:rrf:k={WEB_SEARCH_RRF_K}"));
    lines
}

/// Per-provider ranked entry consumed by [`reciprocal_rank_fusion`].
///
/// `provider_id` is the registry id (e.g. `"duckduckgo"`), `rank` is the
/// 1-based position the provider returned for the URL, and `title`/`excerpt`
/// preserve the human-readable metadata for the first appearance.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ProviderRanking {
    pub provider_id: String,
    pub rank: u32,
    pub url: String,
    pub title: String,
    pub excerpt: String,
}

/// Single fused row produced by [`reciprocal_rank_fusion`].
///
/// `score` is the RRF sum; `providers` lists the contributing
/// `provider#rank` pairs in insertion order so the JS side can render
/// "via duckduckgo#3, wikipedia#1" inline.
#[derive(Debug, Clone, PartialEq)]
pub struct FusedEntry {
    pub url: String,
    pub title: String,
    pub excerpt: String,
    pub score: f64,
    pub providers: Vec<(String, u32)>,
}

/// Search-provider response plus the capture proving where its rankings came
/// from.
#[cfg(not(target_arch = "wasm32"))]
#[derive(Debug, Clone, PartialEq)]
pub struct SearchExecution {
    pub captures: Vec<crate::source_fetch::SourceCapture>,
    pub rankings: Vec<ProviderRanking>,
    pub fused: Vec<FusedEntry>,
    /// Published component APIs that produced this execution.
    pub component_boundaries: Vec<String>,
    /// Component failures retained when a bounded compatibility path succeeds.
    pub component_diagnostics: Vec<String>,
}

/// Execute `DuckDuckGo` through web-capture's published normalization contract,
/// the common cached fetch boundary, and web-search's published RRF merger.
///
/// The Instant Answer parser remains a bounded compatibility fallback for old
/// caches and deployments blocked by provider HTML. It still crosses the
/// web-search merger boundary, and the execution receipt reports the fallback.
#[cfg(not(target_arch = "wasm32"))]
pub fn execute_duckduckgo_search<T: crate::source_fetch::SourceTransport>(
    client: &crate::source_fetch::CachedSourceClient<T>,
    query: &str,
) -> Result<SearchExecution, crate::source_fetch::FetchError> {
    let component_url = web_capture::search::build_search_url(
        "duckduckgo",
        query,
        WEB_SEARCH_PROVIDER_LIMIT as usize,
    )
    .map_err(crate::source_fetch::FetchError::InvalidUrl)?;
    let mut captures = Vec::new();
    let mut component_diagnostics = Vec::new();
    let mut component_failure = None;
    let component_rows = match client.fetch(&component_url) {
        Ok(capture) => {
            let body = String::from_utf8_lossy(capture.bytes());
            let (rows, blocked) = web_capture::search::parse_search_results(
                "duckduckgo",
                &body,
                WEB_SEARCH_PROVIDER_LIMIT as usize,
            );
            captures.push(capture);
            if blocked {
                component_diagnostics.push(String::from("web-capture:search:blocked"));
            } else if rows.is_empty() {
                component_diagnostics.push(String::from("web-capture:search:empty"));
            }
            (!blocked && !rows.is_empty()).then_some(rows)
        }
        Err(error) => {
            component_failure = Some(error.to_string());
            component_diagnostics.push(String::from("web-capture:search:unavailable"));
            None
        }
    };

    let (rankings, capture_boundary) = if let Some(rows) = component_rows {
        (
            rows.into_iter()
                .map(|row| ProviderRanking {
                    provider_id: String::from("duckduckgo"),
                    rank: u32::try_from(row.rank).unwrap_or(u32::MAX),
                    url: row.url,
                    title: row.title,
                    excerpt: row.snippet,
                })
                .collect::<Vec<_>>(),
            "web-capture:search",
        )
    } else {
        let component_failure_receipt =
            component_failure.unwrap_or_else(|| component_diagnostics.join("; "));
        let (capture, rows) =
            execute_duckduckgo_instant_answer(client, query).map_err(|fallback_error| {
                crate::source_fetch::FetchError::Transport(format!(
                    "web_search_component_failure:{component_failure_receipt};web_search_fallback_failure:{fallback_error}"
                ))
            })?;
        captures.push(capture);
        (rows, "web-capture:search:fallback")
    };
    let fused = fuse_with_web_search(&rankings);
    Ok(SearchExecution {
        captures,
        rankings,
        fused,
        component_boundaries: vec![
            capture_boundary.to_owned(),
            String::from("web-search:merger"),
        ],
        component_diagnostics,
    })
}

#[cfg(not(target_arch = "wasm32"))]
fn execute_duckduckgo_instant_answer<T: crate::source_fetch::SourceTransport>(
    client: &crate::source_fetch::CachedSourceClient<T>,
    query: &str,
) -> Result<
    (crate::source_fetch::SourceCapture, Vec<ProviderRanking>),
    crate::source_fetch::FetchError,
> {
    let url = format!(
        "https://api.duckduckgo.com/?q={}&format=json&no_html=1&skip_disambig=1",
        percent_encode_query(query)
    );
    let capture = client.fetch(&url)?;
    let document: serde_json::Value = serde_json::from_slice(capture.bytes()).map_err(|error| {
        crate::source_fetch::FetchError::Transport(
            ["duckduckgo_invalid_json", &error.to_string()].join(":"),
        )
    })?;
    let mut rows = Vec::new();
    collect_duckduckgo_topics(&document["RelatedTopics"], &mut rows);
    if let (Some(url), Some(text)) = (
        document["AbstractURL"].as_str(),
        document["AbstractText"].as_str(),
    ) && !url.is_empty()
    {
        rows.insert(0, (url.to_owned(), text.to_owned()));
    }
    rows.truncate(10);
    let mut rankings = rows
        .into_iter()
        .enumerate()
        .map(|(index, (url, text))| ProviderRanking {
            provider_id: String::from("duckduckgo"),
            rank: u32::try_from(index + 1).unwrap_or(u32::MAX),
            url,
            title: text.clone(),
            excerpt: text,
        })
        .collect::<Vec<_>>();
    if let Some(heading) = document["Heading"]
        .as_str()
        .filter(|value| !value.is_empty())
        && let Some(first) = rankings.first_mut()
    {
        heading.clone_into(&mut first.title);
    }
    Ok((capture, rankings))
}

#[cfg(not(target_arch = "wasm32"))]
fn fuse_with_web_search(rankings: &[ProviderRanking]) -> Vec<FusedEntry> {
    use std::collections::HashMap;

    let component_rows = rankings
        .iter()
        .map(|ranking| web_search::SearchResult {
            title: ranking.title.clone(),
            url: ranking.url.clone(),
            snippet: ranking.excerpt.clone(),
            source: ranking.provider_id.clone(),
            rank: usize::try_from(ranking.rank).unwrap_or(usize::MAX),
            score: None,
            sources: None,
        })
        .collect::<Vec<_>>();
    let mut by_provider = HashMap::new();
    by_provider.insert(String::from("duckduckgo"), component_rows);
    let options = web_search::MergeOptions::new().with_rrf_k(f64::from(WEB_SEARCH_RRF_K));
    web_search::merger::merge_results(&by_provider, &options)
        .into_iter()
        .map(|result| {
            let original = rankings.iter().find(|ranking| ranking.url == result.url);
            let provider_id = original.map_or_else(
                || result.source.clone(),
                |ranking| ranking.provider_id.clone(),
            );
            let provider_rank = original.map_or_else(
                || u32::try_from(result.rank).unwrap_or(u32::MAX),
                |ranking| ranking.rank,
            );
            FusedEntry {
                url: result.url,
                title: result.title,
                excerpt: result.snippet,
                score: result.score.unwrap_or_default(),
                providers: vec![(provider_id, provider_rank)],
            }
        })
        .collect()
}

#[cfg(not(target_arch = "wasm32"))]
fn collect_duckduckgo_topics(value: &serde_json::Value, rows: &mut Vec<(String, String)>) {
    let Some(items) = value.as_array() else {
        return;
    };
    for item in items {
        if let (Some(url), Some(text)) = (item["FirstURL"].as_str(), item["Text"].as_str()) {
            if !url.is_empty() {
                rows.push((url.to_owned(), text.to_owned()));
            }
        } else {
            collect_duckduckgo_topics(&item["Topics"], rows);
        }
    }
}

#[cfg(not(target_arch = "wasm32"))]
fn percent_encode_query(query: &str) -> String {
    use core::fmt::Write;

    let mut encoded = String::new();
    for byte in query.bytes() {
        if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
            encoded.push(char::from(byte));
        } else {
            write!(encoded, "%{byte:02X}").expect("writing to a String cannot fail");
        }
    }
    encoded
}

/// Compute the reciprocal-rank-fusion ranking for a flat list of provider
/// rows. Equivalent to the JS implementation in `worker/formal_ai_worker.js` and
/// the offline trace in `web_requests.rs`.
#[must_use]
pub fn reciprocal_rank_fusion(entries: &[ProviderRanking], k: u32) -> Vec<FusedEntry> {
    let mut fused: Vec<FusedEntry> = Vec::new();
    for entry in entries {
        if entry.url.is_empty() {
            continue;
        }
        let denom = f64::from(k) + f64::from(entry.rank);
        if denom <= 0.0 {
            continue;
        }
        let score = 1.0 / denom;
        if let Some(existing) = fused.iter_mut().find(|item| item.url == entry.url) {
            existing.score += score;
            existing
                .providers
                .push((entry.provider_id.clone(), entry.rank));
            if existing.title.is_empty() && !entry.title.is_empty() {
                existing.title.clone_from(&entry.title);
            }
            if existing.excerpt.is_empty() && !entry.excerpt.is_empty() {
                existing.excerpt.clone_from(&entry.excerpt);
            }
        } else {
            let providers: Vec<(String, u32)> = vec![(entry.provider_id.clone(), entry.rank)];
            fused.push(FusedEntry {
                url: entry.url.clone(),
                title: if entry.title.is_empty() {
                    entry.url.clone()
                } else {
                    entry.title.clone()
                },
                excerpt: entry.excerpt.clone(),
                score,
                providers,
            });
        }
    }
    fused.sort_by(|left, right| match right.score.partial_cmp(&left.score) {
        Some(Ordering::Equal) | None => right.providers.len().cmp(&left.providers.len()),
        Some(order) => order,
    });
    fused
}

/// Parse the line-delimited byte buffer the WASM worker exchanges with JS.
///
/// Each line is `provider_id\trank\turl\ttitle\texcerpt`. Empty lines are
/// skipped; malformed lines are dropped silently so the JS fallback can
/// recover even when one provider returns junk.
#[must_use]
pub fn parse_rrf_input(input: &str) -> Vec<ProviderRanking> {
    let mut entries: Vec<ProviderRanking> = Vec::new();
    for line in input.split('\n') {
        if line.is_empty() {
            continue;
        }
        let mut parts = line.split('\t');
        let Some(provider_id) = parts.next() else {
            continue;
        };
        let Some(rank_text) = parts.next() else {
            continue;
        };
        let Some(url) = parts.next() else {
            continue;
        };
        let title = parts.next().unwrap_or("");
        let excerpt = parts.next().unwrap_or("");
        let Ok(rank) = rank_text.parse::<u32>() else {
            continue;
        };
        if url.is_empty() {
            continue;
        }
        entries.push(ProviderRanking {
            provider_id: provider_id.to_string(),
            rank,
            url: url.to_string(),
            title: title.to_string(),
            excerpt: excerpt.to_string(),
        });
    }
    entries
}

/// Serialize the fused result list back to the JS side. The format mirrors
/// `parse_rrf_input` for symmetry: one row per line, tab-separated, with
/// the `providers` field encoded as `id#rank` joined by `+`.
#[must_use]
pub fn serialize_rrf_output(fused: &[FusedEntry]) -> String {
    let mut buffer = String::new();
    for entry in fused {
        if !buffer.is_empty() {
            buffer.push('\n');
        }
        buffer.push_str(&entry.url);
        buffer.push('\t');
        buffer.push_str(&entry.title);
        buffer.push('\t');
        buffer.push_str(&entry.excerpt);
        buffer.push('\t');
        buffer.push_str(&format_score(entry.score));
        buffer.push('\t');
        for (index, (provider_id, rank)) in entry.providers.iter().enumerate() {
            if index > 0 {
                buffer.push('+');
            }
            buffer.push_str(provider_id);
            buffer.push('#');
            buffer.push_str(&rank.to_string());
        }
    }
    buffer
}

/// Format an RRF score with six decimal places — enough precision to keep
/// the JS side's tie-break behaviour identical without depending on `std`'s
/// formatter quirks. The `no_std` WASM target does not link the `round`
/// intrinsic, so we do the round-half-away-from-zero conversion by hand.
fn format_score(score: f64) -> String {
    let scaled_f = score * 1_000_000.0;
    let scaled = if scaled_f >= 0.0 {
        (scaled_f + 0.5) as i64
    } else {
        (scaled_f - 0.5) as i64
    };
    let whole = scaled / 1_000_000;
    let fraction = (scaled % 1_000_000).abs();
    let mut text = String::new();
    if scaled < 0 && whole == 0 {
        text.push('-');
    }
    text.push_str(&whole.to_string());
    text.push('.');
    let fraction_str = fraction.to_string();
    for _ in 0..(6 - fraction_str.len()) {
        text.push('0');
    }
    text.push_str(&fraction_str);
    text
}

