{"content":"//! URL fetch, URL navigation, and browser-search handlers.

use crate::concepts::extract_concept_query;
use crate::engine::{SymbolicAnswer, normalize_prompt};
use crate::event_log::EventLog;
use crate::formalization::page::{formalize_page, page_answer};
use crate::language::detect as detect_language;
use crate::seed::{self, ProjectRecord, projects_registry};
use crate::source_fetch::{CachedSourceClient, CurlSourceTransport, FetchError, SourceTransport};
use crate::summarization::{SummarizationConfig, SummarizationMode, describe_project};
use crate::web_search_core::{
    WEB_SEARCH_PROVIDERS as CORE_WEB_SEARCH_PROVIDERS, WEB_SEARCH_RRF_K as CORE_WEB_SEARCH_RRF_K,
};

mod live_search;
mod url_parse;

use super::curated_project_fetch::try_curated_http_fetch;
use super::finalize_simple;
use super::installation_conversion::is_install_conversion_request;
use super::web_search_intent::{WebSearchQueryKind, extract_web_search_request};

pub use live_search::{try_web_search_with_client, try_web_search_with_offline};
pub(super) use url_parse::normalize_url_candidate;
use url_parse::{
    extract_http_fetch_url, extract_url_navigate_url, first_url_candidate,
    is_page_formalization_prompt, is_url_trailing_punctuation, is_url_wrapper_punctuation,
    looks_like_hostname,
};

/// Match prompts that explicitly ask the engine to perform an HTTP request
/// (e.g. `fetch google.com`, `Сделай запрос к google.com`). In the browser
/// web app the actual `fetch()` is attempted first, with an iframe fallback when
/// CORS blocks the request only after target frame-policy headers have been
/// checked. Non-fetch URL prompts (`Navigate to github.com`, `Visit github.com`,
/// ...) are handled by [`try_url_navigate`] instead.
pub fn try_http_fetch(
    prompt: &str,
    normalized: &str,
    log: &mut EventLog,
) -> Option<SymbolicAnswer> {
    try_http_fetch_with_offline(prompt, normalized, log, true)
}

/// Execute an explicit HTTP request when the caller has opted out of offline
/// mode. A failed request records an error, never source provenance.
pub fn try_http_fetch_with_offline(
    prompt: &str,
    normalized: &str,
    log: &mut EventLog,
    offline: bool,
) -> Option<SymbolicAnswer> {
    let url = extract_http_fetch_url(prompt, normalized)?;
    Some(answer_http_fetch_url(prompt, &url, log, offline))
}

/// Execute the URL selected by the shared object/act/locus capability table.
///
/// Unlike [`try_http_fetch_with_offline`], this entry point does not ask a
/// second verb recognizer whether the already-routed request really meant
/// fetch.  The URL remains structural and is parsed from the original prompt;
/// all execution, cache, provenance, and offline behaviour is the same.
pub fn try_routed_http_fetch_with_offline(
    prompt: &str,
    log: &mut EventLog,
    offline: bool,
) -> Option<SymbolicAnswer> {
    let url = crate::capability_routing::first_url(prompt)?;
    Some(answer_http_fetch_url(prompt, &url, log, offline))
}

fn answer_http_fetch_url(
    prompt: &str,
    url: &str,
    log: &mut EventLog,
    offline: bool,
) -> SymbolicAnswer {
    if is_page_formalization_prompt(prompt, &normalize_prompt(prompt)) {
        let cache_root = crate::coding::synthesis_runtime::source_cache_root();
        let client =
            CachedSourceClient::new(&cache_root, CurlSourceTransport).with_online(!offline);
        return answer_page_formalization(prompt, url, log, &client);
    }
    log.append("http_fetch:request", url);
    if let Some(answer) = try_curated_http_fetch(prompt, url, log) {
        return answer;
    }
    if offline {
        log.append("policy:offline", url);
        let body = seed::response_for("lexeme_import_cache_miss_offline", "en")
            .unwrap_or_else(|| String::from("lexeme_import_cache_miss_offline"))
            .replace("{qid}", url);
        return finalize_simple(prompt, log, "http_fetch", "response:http_fetch", &body, 1.0);
    }
    let cache_dir =
        std::env::var("FORMAL_AI_SOURCE_CACHE_DIR").unwrap_or_else(|_| String::from("data"));
    let client = CachedSourceClient::new(cache_dir, CurlSourceTransport).with_online(true);
    let capture = match client.fetch(url) {
        Ok(capture) => capture,
        Err(error) => {
            log.append("error:fetch", error.to_string());
            let body = seed::response_for("lexeme_import_fetch_failed", "en")
                .unwrap_or_else(|| String::from("lexeme_import_fetch_failed"))
                .replace("{qid}", url)
                .replace(&["{", "error", "}"].concat(), &error.to_string());
            return finalize_simple(
                prompt,
                log,
                "http_fetch",
                "response:http_fetch_failed",
                &body,
                0.0,
            );
        }
    };
    capture.record(log);
    let body = String::from_utf8_lossy(capture.bytes())
        .chars()
        .take(8_000)
        .collect::<String>();
    finalize_simple(prompt, log, "http_fetch", "response:http_fetch", &body, 1.0)
}

/// Formalize the page a request names through `client` (R1188-U18).
///
/// The cache answers first, and the network only when the client is
/// online. Returns `None` when the request names no URL or does not ask for
/// a formalization. The browser twin is `tryPageFormalization` in
/// `js/worker/formal_ai_worker_page_formalization.js`.
pub fn try_page_formalization_with_client<T: SourceTransport>(
    prompt: &str,
    log: &mut EventLog,
    client: &CachedSourceClient<T>,
) -> Option<SymbolicAnswer> {
    let normalized = normalize_prompt(prompt);
    let url = extract_http_fetch_url(prompt, &normalized)?;
    is_page_formalization_prompt(prompt, &normalized)
        .then(|| answer_page_formalization(prompt, &url, log, client))
}

/// The statements of the page at `url`, in the request's language: the
/// page's prose ([`crate::web_formalize::page_prose`]) read by
/// [`crate::formalization::page::formalize_page`] in the page's language.
/// Offline with no cached capture, or when the fetch fails, the answer says
/// so and nothing is formalized.
fn answer_page_formalization<T: SourceTransport>(
    prompt: &str,
    url: &str,
    log: &mut EventLog,
    client: &CachedSourceClient<T>,
) -> SymbolicAnswer {
    log.append("page_formalization:request", url);
    let language = detect_language(prompt).slug();
    let capture = match client.fetch(url) {
        Ok(capture) => capture,
        Err(error) => {
            log.append("error:fetch", error.to_string());
            let reason = error.to_string();
            let body = if matches!(error, FetchError::OfflineCacheMiss(_)) {
                seed::render_response("page_formalization_offline", language, &[("url", url)])
            } else {
                seed::render_response(
                    "page_formalization_fetch_failed",
                    language,
                    &[("url", url), ("error", &reason)],
                )
            };
            return finalize_simple(
                prompt,
                log,
                "page_formalization",
                "response:page_formalization_unavailable",
                &body.unwrap_or_default(),
                0.0,
            );
        }
    };
    capture.record(log);
    let prose = crate::web_formalize::page_prose(capture.bytes(), url);
    let report = formalize_page(&prose, detect_language(&prose).slug());
    let counts = [
        report.sentences.len(),
        report.statements,
        report.covered,
        report.terms,
        report.unknown,
    ]
    .map(|count| count.to_string());
    log.append_fields(
        "page_formalization:report",
        &[
            ("sentences", &counts[0]),
            ("statements", &counts[1]),
            ("covered", &counts[2]),
            ("terms", &counts[3]),
            ("unknown", &counts[4]),
        ],
    );
    let body = page_answer(&report, url, language);
    finalize_simple(
        prompt,
        log,
        "page_formalization",
        "response:page_formalization",
        &body,
        0.9,
    )
}

/// Whether the seed's navigation recognizer claims this prompt for the
/// `url_navigate` row (`Open github.com`, `Перейди на …`). The capability
/// table's routed fetch runs ahead of that row and deliberately does not
/// re-ask a verb recognizer, so it asks this instead: a request the
/// navigation vocabulary claims is advice to open a tab, not a fetch of the
/// page (the url-navigation ladder in `seed_and_memory`, issue #1138).
pub fn url_navigation_claims(prompt: &str, normalized: &str) -> bool {
    extract_url_navigate_url(prompt, normalized).is_some()
}

/// Whether the seed's fetch recognizer claims this prompt for the
/// `http_fetch` row: a URL operand the request asks to retrieve. The claim
/// row of the capability table consults it before the handler runs (issue
/// #1175 R3), so a fetch word with no URL operand never reaches it.
#[must_use]
pub fn http_fetch_claims(prompt: &str, normalized: &str) -> bool {
    extract_http_fetch_url(prompt, normalized).is_some()
}

/// Match prompts that ask the assistant to navigate to or display a URL
/// without performing an HTTP request (e.g. `Navigate to github.com`,
/// `Go to github.com`, `Перейди на github.com`). The browser web app renders
/// an iframe preview only when CORS-readable frame-policy metadata does not
/// report blocking X-Frame-Options or CSP frame-ancestors headers.
pub fn try_url_navigate(
    prompt: &str,
    normalized: &str,
    log: &mut EventLog,
) -> Option<SymbolicAnswer> {
    let url = extract_url_navigate_url(prompt, normalized)?;
    log.append("url_navigate:request", url.clone());
    log.append("url_preview:frame_policy_check", url.clone());
    log.append("url_preview:external_link", url.clone());
    // Issue #918: the wording is the seeded web_* responses the browser twin
    // (`tryUrlNavigate`, js/worker/formal_ai_worker_web_providers_and_wasm_calls.js) also renders.
    let body = format!(
        "{}\n\n{}",
        seed::render_response("web_open_in_new_tab", "en", &[("url", &url)]).unwrap_or_default(),
        seed::render_response("web_url_navigate_native_note", "en", &[]).unwrap_or_default(),
    );
    Some(finalize_simple(
        prompt,
        log,
        "url_navigate",
        "response:url_navigate",
        &body,
        0.95,
    ))
}

/// Reciprocal Rank Fusion constant used to combine the top-10 results returned
/// by each search provider. Re-exported from `crate::web_search_core` so the
/// CLI, server, browser worker, and the Rust→WASM port all share one value.
///
/// Source: <https://plg.uwaterloo.ca/~gvcormac/cormacksigir09-rrf.pdf>
pub const WEB_SEARCH_RRF_K: u32 = CORE_WEB_SEARCH_RRF_K;

/// Provider order used by the browser worker and by the Rust solver when
/// recording the unexecuted provider plan for `web_search`. Sourced from
/// `crate::web_search_core::WEB_SEARCH_PROVIDERS` so the WASM worker and the
/// JS planner cannot drift apart (issue #133).
pub const WEB_SEARCH_PROVIDERS: &[&str] = CORE_WEB_SEARCH_PROVIDERS;

/// Execute a recognized web-search request instead of describing one.
///
/// Issue #1173 (E138) R2: this handler used to answer with the fixed
/// paragraph describing the browser demo's provider plan. It now runs the
/// executed search through the process source cache — captured sources
/// answer from their statements with citations, and anything else degrades
/// to the localized `web_search_unavailable` response. Live provider
/// fetches stay opt-in via `FORMAL_AI_LIVE_FETCH`, matching the combined
/// offline gate `solver_dispatch.rs` applies to its `web_search` route.
pub fn try_web_search(
    prompt: &str,
    normalized: &str,
    log: &mut EventLog,
) -> Option<SymbolicAnswer> {
    let request = extract_web_search_request(prompt, normalized)?;
    // The native-handler table carries no runtime offline flag; the live-fetch
    // opt-in is applied inside `answer_web_search_query`.
    Some(answer_web_search_query(
        prompt,
        &request.query,
        request.kind,
        log,
        false,
    ))
}

/// The web-search query the intent recogniser extracts from `prompt`, or [`None`]
/// when the prompt is not a web-search request.
///
/// Exposes the *same* seed-backed recognition [`try_web_search`] uses, without
/// producing the descriptive answer, so the agentic planner (issue #687) can reuse
/// it to decide when to emit the client's web-search tool call instead of
/// re-deriving the intent independently.
pub fn detect_web_search_query(prompt: &str) -> Option<String> {
    let normalized = prompt.to_lowercase();
    extract_web_search_request(prompt, &normalized).map(|request| request.query)
}

/// Execute the web search for `query` and answer from it.
///
/// Issue #1173 (E138): this function used to build the descriptive paragraph
/// about the browser demo's search machinery ("Web search requested for
/// `…`" and its latest-news, research, and Russian arms), which stood as the
/// final answer for every prompt the intent recogniser or the
/// unknown-reasoning fallback handed it. The description is deleted as an
/// answer surface: the search now executes through the process source cache
/// (issue #709 fusion) and answers from the captured statements with
/// citations, or — offline or on a cache miss — with the localized
/// `web_search_unavailable` response that names the query.
///
/// `runtime_offline` is the caller's own offline mode; the
/// `FORMAL_AI_LIVE_FETCH` opt-in is applied here so every caller gets the
/// combined offline gate `solver_dispatch.rs` uses at its `web_search` call
/// site.
pub fn answer_web_search_query(
    prompt: &str,
    query: &str,
    query_kind: WebSearchQueryKind,
    log: &mut EventLog,
    runtime_offline: bool,
) -> SymbolicAnswer {
    let cache_dir =
        std::env::var("FORMAL_AI_SOURCE_CACHE_DIR").unwrap_or_else(|_| String::from("data"));
    let client = CachedSourceClient::new(cache_dir, CurlSourceTransport)
        .with_online(!runtime_offline && live_search::live_fetch_enabled());
    live_search::execute_web_search_answer(prompt, query, query_kind, log, &client)
}

const PROMOTED_PROJECT_ORGS: &[&str] = &["link-assistant", "link-foundation", "linksplatform", "deep-foundation"];

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum RepositoryPlatform {
    GitHub,
    GitLab,
    Bitbucket,
}

impl RepositoryPlatform {
    const fn label(self) -> &'static str {
        match self {
            Self::GitHub => "GitHub",
            Self::GitLab => "GitLab",
            Self::Bitbucket => "Bitbucket",
        }
    }

    const fn host(self) -> &'static str {
        match self {
            Self::GitHub => "github.com",
            Self::GitLab => "gitlab.com",
            Self::Bitbucket => "bitbucket.org",
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
struct RepositoryReference {
    platform: RepositoryPlatform,
    owner: String,
    name: String,
    url: String,
}

impl RepositoryReference {
    fn slug(&self) -> String {
        format!("{}/{}", self.owner, self.name)
    }
}

/// Lookup repository/project prompts. Runs *after* `concept_lookup` so
/// seed-backed concept terms (`Links Notation`, `Wikipedia`, `Rust`, …) keep their intent.
///
/// With promotion enabled (the default), known projects from Link Assistant,
/// Link Foundation, and `LinksPlatform` are listed first. With promotion
/// disabled, the same prompts stay on the generic repository lookup path.
pub fn try_project_lookup(
    prompt: &str,
    _normalized: &str,
    log: &mut EventLog,
    promote_associative_repositories: bool,
    suppress_identity_route: bool,
) -> Option<SymbolicAnswer> {
    try_project_lookup_internal(
        prompt,
        prompt,
        log,
        promote_associative_repositories,
        suppress_identity_route,
        None,
    )
}

pub fn try_explicit_repository_lookup(
    prompt: &str,
    normalized: &str,
    log: &mut EventLog,
    promote_associative_repositories: bool,
    suppress_identity_route: bool,
    response_language: Option<&str>,
) -> Option<SymbolicAnswer> {
    if is_text_url_extraction_prompt(normalized) {
        return None;
    }
    if extract_http_fetch_url(prompt, normalized).is_some()
        || extract_url_navigate_url(prompt, normalized).is_some()
    {
        return None;
    }
    repository_from_prompt(prompt)?;
    try_project_lookup_internal(
        prompt,
        prompt,
        log,
        promote_associative_repositories,
        suppress_identity_route,
        response_language,
    )
}

pub fn try_project_lookup_with_response_language(
    prompt: &str,
    lookup_prompt: &str,
    log: &mut EventLog,
    promote_associative_repositories: bool,
    suppress_identity_route: bool,
    response_language: &str,
) -> Option<SymbolicAnswer> {
    try_project_lookup_internal(
        prompt,
        lookup_prompt,
        log,
        promote_associative_repositories,
        suppress_identity_route,
        Some(response_language),
    )
}

fn try_project_lookup_internal(
    prompt: &str,
    lookup_prompt: &str,
    log: &mut EventLog,
    promote_associative_repositories: bool,
    suppress_identity_route: bool,
    response_language: Option<&str>,
) -> Option<SymbolicAnswer> {
    // A repository URL can be source material rather than the requested action.
    // Keep installation-guide/script transformations on their more specific
    // conversion path instead of treating the embedded clone URL as a lookup.
    if is_install_conversion_request(&lookup_prompt.to_lowercase()) {
        return None;
    }
    if is_text_url_extraction_prompt(lookup_prompt) {
        return None;
    }
    if let Some(repo) = repository_from_prompt(lookup_prompt) {
        if promote_associative_repositories
            && let Some(project) = promoted_project_by_repo(&repo.owner, &repo.name)
        {
            return Some(render_project_lookup(
                prompt,
                log,
                project,
                response_language,
            ));
        }
        return Some(render_generic_repository_lookup(
            prompt,
            log,
            Some(&repo),
            promote_associative_repositories,
            response_language,
        ));
    }
    if suppress_identity_route {
        return None;
    }

    let project = matched_project(lookup_prompt)?;
    if promote_associative_repositories && is_promoted_project(project) {
        return Some(render_project_lookup(
            prompt,
            log,
            project,
            response_language,
        ));
    }

    Some(render_generic_repository_lookup(
        prompt,
        log,
        None,
        promote_associative_repositories,
        response_language,
    ))
}

fn render_project_lookup(
    prompt: &str,
    log: &mut EventLog,
    project: &ProjectRecord,
    response_language: Option<&str>,
) -> SymbolicAnswer {
    let language = response_language.unwrap_or_else(|| detect_language(prompt).slug());
    // Issue #556: record the forced target language so a response-language
    // replay's trace and evidence carry `language_to:<code>` even though the
    // localized surface itself is produced by the summarizer below.
    if response_language.is_some() {
        log.append("language_to", language.to_owned());
    }
    let config = SummarizationConfig::default()
        .with_mode(SummarizationMode::Short)
        .with_language(language);
    let description = describe_project(project, &config);
    let display_name = project.display_name_for(language);
    let repo_slug = project.repo_slug();
    let project_url = project.url.clone();

    log.append("project:promoted", repo_slug.clone());
    log.append("source", project_url.clone());
    log.append("summarization:mode", "short".to_owned());
    log.append("summarization:language", language.to_owned());
    log.append("web_search:request", display_name.to_owned());
    for provider in WEB_SEARCH_PROVIDERS {
        log.append("web_search:provider_planned", (*provider).to_owned());
    }
    log.append(
        "web_search:fusion_planned",
        format!("rrf:k={WEB_SEARCH_RRF_K}"),
    );

    let provider_summary = WEB_SEARCH_PROVIDERS.join(", ");
    let promoted_orgs = PROMOTED_PROJECT_ORGS.join(", ");
    let fusion_constant = WEB_SEARCH_RRF_K.to_string();
    let body = seed::fill_template_once(
        &seed::localized_response("project-lookup-promoted", language).unwrap_or_default(),
        &[
            ("promoted-orgs", &promoted_orgs),
            ("display-name", display_name),
            ("repo-slug", &repo_slug),
            ("project-url", &project_url),
            ("description", &description),
            ("provider-summary", &provider_summary),
            ("reciprocal-rank-constant", &fusion_constant),
        ],
    );
    finalize_simple(
        prompt,
        log,
        "project_lookup",
        "response:project_lookup",
        &body,
        0.9,
    )
}

fn render_generic_repository_lookup(
    prompt: &str,
    log: &mut EventLog,
    repository: Option<&RepositoryReference>,
    promotion_enabled: bool,
    response_language: Option<&str>,
) -> SymbolicAnswer {
    let language = response_language.unwrap_or_else(|| detect_language(prompt).slug());
    // Issue #556: mirror the promoted-project renderer — a forced response
    // language is recorded on the trace so the whole answerable class, not just
    // promoted projects, carries `language_to:<code>` when replayed.
    if response_language.is_some() {
        log.append("language_to", language.to_owned());
    }
    let provider_summary = ["GitHub", "GitLab", "Bitbucket"].join(", ");
    if !promotion_enabled {
        log.append("project_lookup:promotion", "disabled".to_owned());
    }
    if let Some(repo) = repository {
        let slug = repo.slug();
        append_repository_evidence(log, repo.platform, slug.clone());
        log.append("source", repo.url.clone());
        let label = repo.platform.label();
        let body = match language {
            "ru" => format!(
                "Это запрос о репозитории [{slug}]({url}) на {label}.\n\n\
                 Обычный путь project_lookup ищет и резюмирует README или описание \
                 проекта на GitHub, GitLab и Bitbucket без особого правила для \
                 отдельного названия. Если репозиторий находится в продвигаемых \
                 организациях и продвижение включено, он будет показан первым.",
                url = repo.url
            ),
            "hi" => format!(
                "यह {label} पर रिपॉजिटरी [{slug}]({url}) के लिए lookup है.\n\n\
                 Generic project_lookup path GitHub, GitLab, और Bitbucket पर \
                 README या project descriptions summarize कर सकता है, किसी \
                 single name के लिए special case के बिना. अगर repository \
                 promoted organizations में है और promotion enabled है, तो वह \
                 पहले दिखाई जाएगी.",
                url = repo.url
            ),
            "zh" => format!(
                "这是 {label} 上的仓库查询：[{slug}]({url})。\n\n\
                 通用 project_lookup 路径可以汇总 GitHub、GitLab 和 Bitbucket 上的 \
                 README 或项目描述，不需要为单个名称写特殊规则。如果该仓库属于 promoted \
                 organizations 且 promotion 已开启，它会优先显示。",
                url = repo.url
            ),
            _ => format!(
                "This is a repository lookup for [{slug}]({url}) on {label}.\n\n\
                 The generic project_lookup path can summarize README or project \
                 descriptions from GitHub, GitLab, and Bitbucket without a special \
                 case for any single name. If the repository belongs to a promoted \
                 organization and promotion is enabled, that repository is listed \
                 first.",
                url = repo.url
            ),
        };
        return finalize_simple(
            prompt,
            log,
            "project_lookup",
            "response:project_lookup",
            &body,
            0.82,
        );
    }

    log.append("project_lookup:repository_hosts", provider_summary.clone());
    let body = match language {
        "ru" => format!(
            "Это обычный запрос project_lookup о проекте или репозитории.\n\n\
             Я не выделяю специальный репозиторий, потому что продвижение \
             ассоциативных репозиториев отключено. Дальше следует искать и \
             резюмировать подходящие проекты на {provider_summary} и похожих \
             хостингах."
        ),
        "hi" => format!(
            "यह project या repository के लिए generic project_lookup request है.\n\n\
             मैं किसी specific repository को प्राथमिकता नहीं दे रहा हूँ क्योंकि \
             associative repository promotion disabled है. अगला step {provider_summary} \
             और similar hosts पर matching projects खोजना और summarize करना है."
        ),
        "zh" => format!(
            "这是一个关于项目或仓库的通用 project_lookup 请求。\n\n\
             我不会优先选择某个特定仓库，因为 associative repository promotion 已关闭。\
             下一步是在 {provider_summary} 和类似托管平台中搜索并汇总匹配项目。"
        ),
        _ => format!(
            "This is a generic project_lookup request for a project or repository.\n\n\
             I am not privileging a specific repository because associative \
             repository promotion is disabled. The next step is to search and \
             summarize matching projects across {provider_summary} and similar \
             hosts."
        ),
    };
    finalize_simple(
        prompt,
        log,
        "project_lookup",
        "response:project_lookup",
        &body,
        0.72,
    )
}

fn append_repository_evidence(log: &mut EventLog, platform: RepositoryPlatform, slug: String) {
    let kind = match platform {
        RepositoryPlatform::GitHub => "project_lookup:repository:github",
        RepositoryPlatform::GitLab => "project_lookup:repository:gitlab",
        RepositoryPlatform::Bitbucket => "project_lookup:repository:bitbucket",
    };
    log.append(kind, slug);
}

/// Match the concept term against the curated project registry. Returns the
/// matching [`ProjectRecord`] or `None` when no curated project matches.
fn matched_project(prompt: &str) -> Option<&'static ProjectRecord> {
    let query = extract_concept_query(prompt)?;
    let term = normalize_concept_term(&query.term);
    if term.is_empty() {
        return None;
    }
    let registry = registry_static();
    if let Some(project) = registry.by_alias(&term) {
        return Some(project);
    }
    if term == "hivemind" {
        return registry.by_alias("hive mind");
    }
    None
}

fn promoted_project_by_repo(org: &str, name: &str) -> Option<&'static ProjectRecord> {
    let registry = registry_static();
    registry.projects.iter().find(|project| {
        is_promoted_project(project)
            && project.org.eq_ignore_ascii_case(org)
            && project.name.eq_ignore_ascii_case(name)
    })
}

fn is_promoted_project(project: &ProjectRecord) -> bool {
    PROMOTED_PROJECT_ORGS
        .iter()
        .any(|org| project.org.eq_ignore_ascii_case(org))
}

fn repository_from_prompt(prompt: &str) -> Option<RepositoryReference> {
    first_url_candidate(prompt)
        .and_then(|(_, url)| repository_from_url(&url))
        .or_else(|| repository_from_concept_term(prompt))
}

fn repository_from_concept_term(prompt: &str) -> Option<RepositoryReference> {
    let query = extract_concept_query(prompt)?;
    let term = query.term.trim();
    if term.contains("://") || looks_like_hostname(term) {
        return normalize_url_candidate(term).and_then(|url| repository_from_url(&url));
    }
    repository_from_slug(term)
}

fn repository_from_slug(term: &str) -> Option<RepositoryReference> {
    let trimmed = term
        .trim()
        .trim_matches(is_url_wrapper_punctuation)
        .trim_end_matches(is_url_trailing_punctuation);
    let mut segments = trimmed.split('/');
    let owner = clean_repository_segment(segments.next()?)?;
    let name = clean_repository_segment(segments.next()?)?;
    if segments.next().is_some() {
        return None;
    }
    if owner.chars().all(|ch| ch.is_ascii_digit()) && name.chars().all(|ch| ch.is_ascii_digit()) {
        return None;
    }
    Some(RepositoryReference {
        platform: RepositoryPlatform::GitHub,
        url: format!("https://github.com/{owner}/{name}"),
        owner,
        name,
    })
}

fn repository_from_url(url: &str) -> Option<RepositoryReference> {
    let after_scheme = url.split_once("://")?.1;
    let (host_port, path_with_suffix) = after_scheme.split_once('/')?;
    let host = host_port
        .split(':')
        .next()
        .unwrap_or_default()
        .trim_start_matches("www.")
        .to_ascii_lowercase();
    let platform = match host.as_str() {
        "github.com" => RepositoryPlatform::GitHub,
        "gitlab.com" => RepositoryPlatform::GitLab,
        "bitbucket.org" => RepositoryPlatform::Bitbucket,
        _ => return None,
    };
    let path = path_with_suffix
        .split(['?', '#'])
        .next()
        .unwrap_or_default();
    let mut segments = path.split('/').filter(|segment| !segment.is_empty());
    let owner = clean_repository_segment(segments.next()?)?;
    let name = clean_repository_segment(segments.next()?)?;
    Some(RepositoryReference {
        platform,
        url: format!("https://{}/{owner}/{name}", platform.host()),
        owner,
        name,
    })
}

/// Owner/name slugs a prompt names: a GitHub URL's owner and name, then each
/// bare `owner/name` run of the characters a repository slug is spelled with.
///
/// Issue #1175 R3: the repository a traffic question names. Twin of
/// `repositorySlugCandidates` in `js/worker/formal_ai_worker_claim_operands.js`.
#[must_use]
pub fn repository_slug_candidates(prompt: &str) -> Vec<String> {
    let mut slugs = Vec::new();
    if let Some(repo) = first_url_candidate(prompt).and_then(|(_, url)| repository_from_url(&url))
        && repo.platform == RepositoryPlatform::GitHub
    {
        slugs.push(format!("{}/{}", repo.owner, repo.name));
    }
    let leads = |segment: &str| {
        segment
            .chars()
            .next()
            .is_some_and(|ch| ch.is_ascii_alphanumeric())
    };
    let digits = |segment: &str| segment.chars().all(|ch| ch.is_ascii_digit());
    for run in prompt
        .split(|ch: char| !(ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '/' | '-')))
    {
        let mut parts = run.trim_end_matches('.').split('/');
        let (Some(owner), Some(name), None) = (parts.next(), parts.next(), parts.next()) else {
            continue;
        };
        let (Some(owner), Some(name)) = (
            clean_repository_segment(owner),
            clean_repository_segment(name),
        ) else {
            continue;
        };
        if leads(&owner) && leads(&name) && !(digits(&owner) && digits(&name)) {
            slugs.push(format!("{owner}/{name}"));
        }
    }
    slugs
}

fn clean_repository_segment(segment: &str) -> Option<String> {
    let trimmed = segment.trim().trim_end_matches(".git");
    if trimmed.is_empty() {
        return None;
    }
    if !trimmed
        .chars()
        .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '-' | '_' | '.'))
    {
        return None;
    }
    Some(trimmed.to_owned())
}

fn is_text_url_extraction_prompt(normalized: &str) -> bool {
    let normalized = normalized.trim_start().to_ascii_lowercase();
    (normalized.starts_with("extract url ") || normalized.starts_with("extract urls "))
        && normalized.contains(" from ")
}

fn normalize_concept_term(value: &str) -> String {
    normalize_prompt(value)
        .replace(['-', '_'], " ")
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
}

/// Lazy-init the curated projects registry once per process. The seed file is
/// embedded via `include_str!` and the parsed form is immutable, so a `OnceLock`
/// is enough and avoids re-parsing on every prompt.
pub(super) fn registry_static() -> &'static crate::seed::ProjectsRegistry {
    use std::sync::OnceLock;
    static REGISTRY: OnceLock<crate::seed::ProjectsRegistry> = OnceLock::new();
    REGISTRY.get_or_init(projects_registry)
}
